def find(a, x):
    i = 0
    while i < len(a) and a[i] != x:
        i += 1
    return i

def bt(nums, prefix, res):
    if len(prefix) == len(nums):
        res.append(prefix[:])
        return
    for x in nums:
        if x in prefix:
            continue
        prefix.append(x)
        bt(nums, prefix, res)
        # missing: prefix.pop()

res = []
