def f(a):
    lo, mid, hi = 0, 0, len(a) - 1
    while mid <= hi:
        if a[mid] == 0:
            a[lo], a[mid] = a[mid], a[lo]
            lo += 1
            mid += 1
        elif a[mid] == 1:
            mid += 1
        else:
            a[mid], a[hi] = a[hi], a[mid]
            hi -= 1
            mid += 1
    return a

print(f([1, 2, 0]))

def n_rooks(n):
    count = 0
    cols = [False] * n

    def bt(r):
        nonlocal count
        if r == n:
            count += 1
            return
        for c in range(n):
            if cols[c]:
                continue
            cols[c] = True
            bt(r + 1)
            cols[c] = False

    bt(0)
    return count

def comb(candidates, target):
    candidates.sort()
    res = []
    def bt(start, remain, path):
        if remain == 0:
            res.append(path[:])
            return
        for i in range(start, len(candidates)):
            if i > 0 and candidates[i] == candidates[i - 1]:
                continue
            if candidates[i] > remain:
                break
            path.append(candidates[i])
            bt(i + 1, remain - candidates[i], path)
            path.pop()
    bt(0, target, [])
    return res

