def restore(s):
    res = []
    def bt(i, parts):
        if i == len(s) and len(parts) == 4:
            res.append('.'.join(parts))
            return
        if len(parts) == 4:
            return
        for j in range(i + 1, min(i + 4, len(s) + 1)):
            seg = s[i:j]
            if (len(seg) > 1 and seg[0] == '0') or int(seg) > 255:
                continue
            bt(j, parts + [seg])
    bt(0, [])
    return res
